Invalid arguments for tool "edit":
- path: Missing key

Arguments provided:
{
  "oldString": "</main>
<script>
",
  "newString": "</main>
<script>
(() => {
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const ui = {
    toast: document.getElementById('toast'),
    interact: document.getElementById('interact'),
    meters: document.getElementById('meters'),
    condition: document.getElementById('condition'),
    clock: document.getElementById('clock'),
    weather: document.querySelector('.weather'),
    objective: document.getElementById('objectiveText'),
    location: document.getElementById('locationName'),
    dayNum: document.getElementById('dayNum'),
    compass: document.getElementById('compass'),
    hotbar: document.getElementById('hotbar'),
    invList: document.getElementById('invList'),
    invWeight: document.getElementById('invWeight'),
    capacity: document.getElementById('capacity'),
    capacityFill: document.getElementById('capacityFill'),
    closeInv: document.getElementById('closeInv'),
    inventory: document.getElementById('inventory')
  };

  const WIDTH = 1600;
  const HEIGHT = 1600;
  const CAPACITY = 24;
  const ITEM_INFO = {
    wood: { name: 'Wood', icon: '🪵', weight: 1.4 },
    rag: { name: 'Rag', icon: '🧵', weight: 0.5 },
    food: { name: 'Food', icon: '🥫', weight: 0.9 },
    medicine: { name: 'Meds', icon: '💊', weight: 1.2 },
    scrap: { name: 'Scrap', icon: '⚙', weight: 0.7 },
    fireKit: { name: 'Campfire Kit', icon: '🔥', weight: 1.7 },
    bandage: { name: 'Bandage', icon: '🩹', weight: 0.6 }
  };

  const state = {
    running: true,
    pause: false,
    day: 1,
    timeMinutes: 6 * 60 + 42,
    weather: 'OVERCAST',
    worldSeed: Math.random(),
    objectiveStage: 0,
    recentToast: '',
    interactable: null,
    campfire: { x: 930, y: 820, active: false, radius: 40 },
    player: {
      x: 420,
      y: 815,
      radius: 12,
      speed: 150,
      health: 100,
      stamina: 100,
      hunger: 82,
      thirst: 72,
      dirX: 1,
      dirY: 0,
      sprinting: false,
      flashlight: false,
      attackCooldown: 0,
      hurtFlash: 0,
      invulnerable: 0
    },
    inventory: {
      wood: 0,
      rag: 0,
      food: 0,
      medicine: 0,
      scrap: 0,
      fireKit: 0,
      bandage: 0
    },
    enemies: [],
    resources: [
      { id: 'log1', x: 260, y: 1040, type: 'wood', amount: 1, label: 'Log pile', radius: 18, collected: false },
      { id: 'log2', x: 520, y: 1240, type: 'wood', amount: 1, label: 'Timber stack', radius: 18, collected: false },
      { id: 'log3', x: 1040, y: 360, type: 'wood', amount: 1, label: 'Shelter wood', radius: 18, collected: false },
      { id: 'rag1', x: 540, y: 660, type: 'rag', amount: 2, label: 'Rag bundle', radius: 18, collected: false },
      { id: 'rag2', x: 1040, y: 1160, type: 'rag', amount: 2, label: 'Shed cloth', radius: 18, collected: false },
      { id: 'food1', x: 1110, y: 830, type: 'food', amount: 1, label: 'Canned stash', radius: 18, collected: false },
      { id: 'med1', x: 845, y: 1180, type: 'medicine', amount: 1, label: 'First aid tin', radius: 18, collected: false },
      { id: 'scrap1', x: 1180, y: 600, type: 'scrap', amount: 1, label: 'Junk crate', radius: 16, collected: false }
    ],
    structures: [
      { x: 220, y: 300, w: 220, h: 170, type: 'barn', tint: '#2d403a' },
      { x: 680, y: 220, w: 170, h: 150, type: 'house', tint: '#354b43' },
      { x: 980, y: 250, w: 240, h: 160, type: 'garage', tint: '#2f3d38' },
      { x: 1260, y: 960, w: 200, h: 160, type: 'warehouse', tint: '#24352e' },
      { x: 480, y: 1040, w: 170, h: 180, type: 'shed', tint: '#2a3c35' },
      { x: 820, y: 950, w: 220, h: 180, type: 'shop', tint: '#32473e' }
    ],
    quickSlots: [
      { key: '1', type: 'medicine' },
      { key: '2', type: 'food' },
      { key: '3', type: 'bandage' },
      { key: '4', type: 'fireKit' }
    ],
    minimap: { x: 20, y: 20, size: 140 }
  };

  function resizeCanvas() {
    const scale = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = window.innerWidth * scale;
    canvas.height = window.innerHeight * scale;
    ctx.setTransform(scale, 0, 0, scale, 0, 0);
  }

  function clamp(value, min, max) {
    return Math.min(max, Math.max(min, value));
  }

  function formatClock(minutes) {
    const total = ((minutes % (24 * 60)) + 24 * 60) % (24 * 60);
    const h = Math.floor(total / 60);
    const m = Math.round(total % 60);
    return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
  }

  function setToast(text, ms = 1600) {
    ui.toast.textContent = text;
    ui.toast.classList.add('show');
    clearTimeout(setToast.tid);
    setToast.tid = setTimeout(() => ui.toast.classList.remove('show'), ms);
  }

  function updateLocationText() {
    let location = 'MILLER\'S CROSSING';
    const x = state.player.x;
    const y = state.player.y;
    if (x > 920 && y < 520) location = 'GREY RAIL';
    else if (x > 920 && y > 520) location = 'SWAMP DISTRICT';
    else if (x < 520 && y > 980) location = 'BLACK HOLLOW';
    else if (x < 500 && y < 700) location = 'CROSSROAD';
    ui.location.textContent = location;
  }

  function getInventoryWeight() {
    return Object.entries(state.inventory).reduce((sum, [key, count]) => {
      return sum + (ITEM_INFO[key]?.weight || 0) * count;
    }, 0);
  }

  function refreshInventory() {
    const weight = getInventoryWeight();
    const capacityPct = (weight / CAPACITY) * 100;
    ui.invWeight.textContent = weight.toFixed(1);
    ui.capacity.textContent = `${weight.toFixed(1)} / ${CAPACITY} KG`;
    ui.capacityFill.style.width = `${clamp(capacityPct, 0, 100)}%`;

    const slots = [];
    for (const [key, item] of Object.entries(state.inventory)) {
      if (item > 0) {
        slots.push(`
          <div class="item">
            <div class="iicon">${ITEM_INFO[key]?.icon || '◈'}</div>
            <strong>${ITEM_INFO[key]?.name || key}</strong>
            <small>x${item}</small>
            <button data-item="${key}">USE</button>
          </div>
        `);
      }
    }
    if (!slots.length) {
      slots.push('<div class="item"><div class="iicon">◎</div><strong>Empty</strong><small>Nothing to carry</small></div>');
    }
    ui.invList.innerHTML = slots.join('');

    ui.invList.querySelectorAll('[data-item]').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const item = e.currentTarget.dataset.item;
        useItem(item, true);
      });
    });

    renderHotbar();
  }

  function renderHotbar() {
    const hotbarHtml = state.quickSlots.map((slot) => {
      const item = state.inventory[slot.type] || 0;
      return `
        <div class="slot ${slot.type === 'fireKit' && state.inventory.fireKit > 0 ? 'active' : ''}" data-slot="${slot.key}">
          <span class="key">${slot.key}</span>
          <span class="icon">${ITEM_INFO[slot.type]?.icon || '◈'}</span>
          <span class="count">${item}</span>
        </div>
      `;
    }).join('');
    ui.hotbar.innerHTML = hotbarHtml;
    document.querySelectorAll('.slot').forEach((slotEl) => {
      slotEl.addEventListener('click', () => {
        const slot = slotEl.dataset.slot;
        const data = state.quickSlots.find((s) => s.key === slot);
        if (data) useItem(data.type, false);
      });
    });
  }

  function useItem(type, fromInventory = false) {
    if (state.player.health <= 0) return;
    if (!state.inventory[type] || state.inventory[type] <= 0) {
      setToast(`No ${ITEM_INFO[type]?.name || type.toUpperCase()} available.`);
      return;
    }

    if (type === 'food') {
      state.player.hunger = clamp(state.player.hunger + 30, 0, 100);
      state.inventory.food--;
      setToast('You eat. Hunger recovered.');
    } else if (type === 'medicine') {
      state.player.health = clamp(state.player.health + 28, 0, 100);
      state.inventory.medicine--;
      setToast('Field medicine applied.');
    } else if (type === 'bandage') {
      state.player.health = clamp(state.player.health + 18, 0, 100);
      state.inventory.bandage--;
      setToast('Bandaged the worst of it.');
    } else if (type === 'fireKit') {
      if (Math.hypot(state.player.x - state.campfire.x, state.player.y - state.campfire.y) < 90) {
        state.campfire.active = true;
        state.inventory.fireKit--;
        state.objectiveStage = 2;
        setToast('Campfire lit. The night will be survivable.');
      } else {
        setToast('The fire kit needs to be set at the campfire site.');
      }
    } else {
      setToast('This item has no use right now.');
    }

    if (fromInventory) refreshInventory();
    else refreshInventory();
  }

  function craftItem(type) {
    if (state.player.health <= 0) return;
    if (type === 'fire') {
      if (state.inventory.wood >= 3 && state.inventory.rag >= 1) {
        state.inventory.wood -= 3;
        state.inventory.rag -= 1;
        state.inventory.fireKit += 1;
        state.objectiveStage = 1;
        setToast('Campfire kit crafted.');
      } else {
        setToast('Need 3 wood and 1 rag.');
      }
    } else if (type === 'bandage') {
      if (state.inventory.rag >= 2) {
        state.inventory.rag -= 2;
        state.inventory.bandage += 1;
        setToast('Cloth bandage made.');
      } else {
        setToast('Need 2 rags.');
      }
    }
    refreshInventory();
  }

  function updateObjectiveText() {
    const p = state.player;
    const nearCamp = Math.hypot(p.x - state.campfire.x, p.y - state.campfire.y) < 95;
    const hasCampKit = state.inventory.fireKit > 0;

    if (state.objectiveStage === 0) {
      ui.objective.textContent = 'Scavenge 3 wood and 2 rags. Use E near the supply points.';
      if (state.inventory.wood >= 3 && state.inventory.rag >= 2) {
        state.objectiveStage = 1;
      }
    } else if (state.objectiveStage === 1) {
      ui.objective.textContent = 'Craft a campfire kit using the field inventory.';
      if (hasCampKit) {
        state.objectiveStage = 2;
      }
    } else if (state.objectiveStage === 2) {
      ui.objective.textContent = 'Reach the campfire site and set the kit before nightfall.';
      if (nearCamp && hasCampKit) {
        useItem('fireKit', false);
      }
    } else {
      ui.objective.textContent = 'Hold the line until sunrise.';
    }

    if (state.campfire.active && state.timeMinutes >= 18 * 60) {
      ui.objective.textContent = 'Sunrise is coming. Hold until morning.';
    }

    if (state.campfire.active && state.timeMinutes >= 20 * 60 && state.player.health > 0) {
      state.running = false;
      setToast('Dawn breaks. You survived the night.', 3500);
      ui.objective.textContent = 'Survival secured — Deadwater County holds.';
      ui.condition.textContent = 'SURVIVED';
    }
  }

  function spawnEnemy() {
    const edge = Math.floor(Math.random() * 4);
    let x = 0;
    let y = 0;
    if (edge === 0) { x = Math.random() * WIDTH; y = -24; }
    else if (edge === 1) { x = WIDTH + 24; y = Math.random() * HEIGHT; }
    else if (edge === 2) { x = Math.random() * WIDTH; y = HEIGHT + 24; }
    else { x = -24; y = Math.random() * HEIGHT; }
    state.enemies.push({
      x,
      y,
      radius: 11,
      hp: 45,
      speed: 42 + Math.random() * 18,
      attackCooldown: 0,
      drift: Math.random() * Math.PI * 2
    });
  }

  function spawnWave() {
    const isNight = state.timeMinutes < 7 * 60 || state.timeMinutes >= 18 * 60;
    const target = isNight ? 5 : 2;
    while (state.enemies.length < target) spawnEnemy();
  }

  function updateEnemies(dt) {
    const p = state.player;
    for (let i = state.enemies.length - 1; i >= 0; i--) {
      const e = state.enemies[i];
      const dx = p.x - e.x;
      const dy = p.y - e.y;
      const dist = Math.hypot(dx, dy) || 1;

      if (dist < 180) {
        e.x += (dx / dist) * e.speed * dt;
        e.y += (dy / dist) * e.speed * dt;
      } else {
        e.drift += dt * 1.8;
        e.x += Math.cos(e.drift) * 20 * dt;
        e.y += Math.sin(e.drift) * 20 * dt;
      }

      if (dist < p.radius + e.radius + 8) {
        e.attackCooldown -= dt;
        if (e.attackCooldown <= 0) {
          state.player.health = clamp(state.player.health - 11, 0, 100);
          e.attackCooldown = 1.2;
          state.player.invulnerable = 0.2;
          state.player.hurtFlash = 0.4;
          setToast('You are under attack!', 500);
        }
      }

      if (e.hp <= 0) {
        state.enemies.splice(i, 1);
        state.inventory.scrap += 1;
        state.inventory.food += 1;
        setToast('Enemy down. Supplies recovered.', 700);
      }
    }
  }

  function updateResourceInteractions() {
    state.interactable = null;
    let best = null;
    const p = state.player;
    for (const resource of state.resources) {
      if (resource.collected) continue;
      const d = Math.hypot(p.x - resource.x, p.y - resource.y);
      if (d < resource.radius + 26) {
        if (!best || d < best.d) {
          best = { d, resource };
        }
      }
    }

    if (best) {
      state.interactable = best.resource;
      ui.interact.textContent = `[E] PICK UP ${best.resource.label.toUpperCase()}`;
      ui.interact.classList.add('show');
    } else if (Math.hypot(p.x - state.campfire.x, p.y - state.campfire.y) < 90) {
      ui.interact.textContent = state.campfire.active ? '[E] CAMPFIRE READY' : '[E] SET CAMPFIRE';
      ui.interact.classList.add('show');
      state.interactable = { type: 'campfire' };
    } else {
      ui.interact.classList.remove('show');
    }
  }

  function collectResource(resource) {
    if (!resource || resource.collected) return;
    const qty = resource.amount || 1;
    if (resource.type === 'wood') state.inventory.wood += qty;
    else if (resource.type === 'rag') state.inventory.rag += qty;
    else if (resource.type === 'food') state.inventory.food += qty;
    else if (resource.type === 'medicine') state.inventory.medicine += qty;
    else if (resource.type === 'scrap') state.inventory.scrap += qty;
    resource.collected = true;
    setToast(`${ITEM_INFO[resource.type]?.name || resource.type} scavenged.`, 700);
    refreshInventory();
  }

  function doInteract() {
    if (!state.running) return;
    if (state.interactable && state.interactable.type === 'campfire') {
      if (state.inventory.fireKit > 0 && !state.campfire.active) {
        state.inventory.fireKit -= 1;
        state.campfire.active = true;
        setToast('Campfire lit. The night has a chance.');
        state.objectiveStage = 3;
        refreshInventory();
        return;
      }
      if (state.campfire.active) {
        setToast('The campfire is already burning.');
      } else {
        setToast('You need a campfire kit first.');
      }
      return;
    }
    if (state.interactable) collectResource(state.interactable);
  }

  function attack() {
    if (state.player.health <= 0 || state.player.attackCooldown > 0) return;
    state.player.attackCooldown = 0.5;

    let nearest = null;
    let nearestDist = 50;
    for (const enemy of state.enemies) {
      const d = Math.hypot(enemy.x - state.player.x, enemy.y - state.player.y);
      if (d < nearestDist) {
        nearest = enemy;
        nearestDist = d;
      }
    }

    if (nearest) {
      nearest.hp -= 35;
      setToast('Target hit.', 240);
    }
  }

  function updatePlayer(dt) {
    const p = state.player;
    const moveX = (keys['KeyD'] || keys['ArrowRight'] ? 1 : 0) - (keys['KeyA'] || keys['ArrowLeft'] ? 1 : 0);
    const moveY = (keys['KeyS'] || keys['ArrowDown'] ? 1 : 0) - (keys['KeyW'] || keys['ArrowUp'] ? 1 : 0);
    const mag = Math.hypot(moveX, moveY) || 1;

    const sprinting = keys['ShiftLeft'] || keys['ShiftRight'];
    p.sprinting = sprinting && p.stamina > 0 && (moveX || moveY);
    const speed = p.sprinting ? p.speed * 1.55 : p.speed;
    const dx = (moveX / mag) * speed * dt;
    const dy = (moveY / mag) * speed * dt;

    p.x += dx;
    p.y += dy;
    p.x = clamp(p.x, 24, WIDTH - 24);
    p.y = clamp(p.y, 24, HEIGHT - 24);

    if (moveX || moveY) {
      p.dirX = moveX / mag;
      p.dirY = moveY / mag;
    }

    if (p.sprinting) p.stamina = clamp(p.stamina - 18 * dt, 0, 100);
    else p.stamina = clamp(p.stamina + 28 * dt, 0, 100);

    p.hunger = clamp(p.hunger - 0.82 * dt, 0, 100);
    p.thirst = clamp(p.thirst - 0.52 * dt, 0, 100);

    if (p.hunger < 25 || p.thirst < 20) {
      p.health = clamp(p.health - 4 * dt, 0, 100);
    }

    if (p.attackCooldown > 0) p.attackCooldown -= dt;
    if (p.hurtFlash > 0) p.hurtFlash -= dt;
    if (p.invulnerable > 0) p.invulnerable -= dt;

    if (p.health <= 0) {
      state.running = false;
      ui.condition.textContent = 'DOWN';
      ui.objective.textContent = 'You were overrun by the night. Reload to try again.';
      setToast('You were overrun. Try again.', 2500);
    }
  }

  function updateUI() {
    const p = state.player;
    const weather = state.timeMinutes >= 18 * 60 || state.timeMinutes < 7 * 60 ? 'NIGHT' : 'OVERCAST';
    ui.clock.textContent = formatClock(state.timeMinutes);
    ui.dayNum.textContent = String(state.day).padStart(2, '0');
    ui.weather.innerHTML = `◌ &nbsp; ${weather} &nbsp; <span class="signal">${Math.round((p.thirst + p.hunger) / 2)}%</span>`;
    ui.compass.textContent = `${compassHeading()} ↑`;

    const healthFill = clamp(p.health, 0, 100);
    const staminaFill = clamp(p.stamina, 0, 100);
    const hungerFill = clamp(p.hunger, 0, 100);

    const metersHtml = `
      <div class="meter"><span>HP</span><div class="track"><div class="fill ${healthFill < 35 ? 'bad' : healthFill < 60 ? 'warn' : ''}" style="width:${healthFill}%"></div></div><b>${Math.round(healthFill)}</b></div>
      <div class="meter"><span>STAM</span><div class="track"><div class="fill ${staminaFill < 25 ? 'warn' : ''}" style="width:${staminaFill}%"></div></div><b>${Math.round(staminaFill)}</b></div>
      <div class="meter"><span>HUN</span><div class="track"><div class="fill ${hungerFill < 25 ? 'bad' : hungerFill < 50 ? 'warn' : ''}" style="width:${hungerFill}%"></div></div><b>${Math.round(hungerFill)}</b></div>
    `;
    ui.meters.innerHTML = metersHtml;

    let condition = 'STABLE';
    if (p.health < 35) condition = 'CRITICAL';
    else if (p.hunger < 35 || p.thirst < 35) condition = 'DEPLETED';
    else if (state.timeMinutes >= 18 * 60 || state.timeMinutes < 7 * 60) condition = 'NIGHT WATCH';
    ui.condition.textContent = condition;
  }

  function compassHeading() {
    const angle = Math.atan2(state.player.dirY, state.player.dirX) * 180 / Math.PI;
    const normalized = (angle + 360 + 90) % 360;
    const sectors = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
    const idx = Math.floor((normalized + 22.5) / 45) % 8;
    return sectors[idx];
  }

  function drawWorld() {
    const timeFrac = (state.timeMinutes / (24 * 60));
    const nightAmount = clamp(1 - (Math.sin((timeFrac - 0.2) * Math.PI * 2) + 1) / 2, 0, 1);
    ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);
    const w = window.innerWidth;
    const h = window.innerHeight;

    const sky = nightAmount > 0.35 ? '#0d1714' : '#d8d3b4';
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, w, h);

    const camX = clamp(state.player.x - w * 0.5, 0, WIDTH - w);
    const camY = clamp(state.player.y - h * 0.5, 0, HEIGHT - h);

    ctx.save();
    ctx.translate(-camX, -camY);

    ctx.fillStyle = nightAmount > 0.45 ? '#1b2b22' : '#324c3d';
    ctx.fillRect(0, 0, WIDTH, HEIGHT);

    for (let i = 0; i < 40; i++) {
      const x = (i * 97) % WIDTH;
      const y = (i * 143 + 60) % HEIGHT;
      ctx.fillStyle = i % 2 ? '#365641' : '#2c4637';
      ctx.fillRect(x, y, 80, 80);
    }

    for (const s of state.structures) {
      ctx.fillStyle = s.tint;
      ctx.fillRect(s.x, s.y, s.w, s.h);
      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      ctx.strokeRect(s.x + 4, s.y + 4, s.w - 8, s.h - 8);
    }

    ctx.strokeStyle = 'rgba(255,255,255,0.12)';
    ctx.lineWidth = 10;
    ctx.beginPath();
    ctx.moveTo(200, 740);
    ctx.lineTo(620, 760);
    ctx.lineTo(865, 640);
    ctx.lineTo(1320, 690);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(420, 1200);
    ctx.lineTo(760, 1060);
    ctx.lineTo(920, 980);
    ctx.lineTo(1180, 1060);
    ctx.stroke();

    for (const resource of state.resources) {
      if (resource.collected) continue;
      ctx.fillStyle = resource.type === 'wood' ? '#a97c52' : resource.type === 'rag' ? '#deca82' : resource.type === 'food' ? '#da9a53' : resource.type === 'medicine' ? '#db6d61' : '#d8d9d1';
      ctx.beginPath();
      ctx.arc(resource.x, resource.y, resource.radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = 'rgba(0,0,0,0.35)';
      ctx.fillText(resource.label, resource.x + 18, resource.y - 14);
    }

    const campColor = state.campfire.active ? '#ffb14a' : '#6b5d4f';
    ctx.fillStyle = campColor;
    ctx.beginPath();
    ctx.arc(state.campfire.x, state.campfire.y, state.campfire.active ? 24 : 16, 0, Math.PI * 2);
    ctx.fill();
    if (state.campfire.active) {
      ctx.fillStyle = '#ffc968';
      ctx.beginPath();
      ctx.arc(state.campfire.x, state.campfire.y - 10, 10, 0, Math.PI * 2);
      ctx.fill();
    }

    for (const enemy of state.enemies) {
      ctx.fillStyle = '#b24949';
      ctx.beginPath();
      ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#2d0909';
      ctx.fillRect(enemy.x - 11, enemy.y - 20, 22, 4);
      ctx.fillStyle = '#f1d2a5';
      ctx.fillRect(enemy.x - 11, enemy.y - 20, (enemy.hp / 45) * 22, 4);
    }

    ctx.fillStyle = '#e9dec0';
    ctx.beginPath();
    ctx.arc(state.player.x, state.player.y, state.player.radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#1b1d1e';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(state.player.x, state.player.y);
    ctx.lineTo(state.player.x + state.player.dirX * 16, state.player.y + state.player.dirY * 16);
    ctx.stroke();

    if (state.player.hurtFlash > 0) {
      ctx.fillStyle = `rgba(255, 82, 82, ${state.player.hurtFlash * 0.8})`;
      ctx.beginPath();
      ctx.arc(state.player.x, state.player.y, state.player.radius + 8, 0, Math.PI * 2);
      ctx.fill();
    }

    if (state.player.flashlight) {
      const grad = ctx.createRadialGradient(state.player.x, state.player.y, 30, state.player.x, state.player.y, 240);
      grad.addColorStop(0, 'rgba(255,255,200,0.35)');
      grad.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = grad;
      ctx.fillRect(state.player.x - 240, state.player.y - 240, 480, 480);
    }

    ctx.restore();

    drawMinimap();
  }

  function drawMinimap() {
    const canvasMini = document.getElementById('minimap');
    const miniCtx = canvasMini.getContext('2d');
    miniCtx.clearRect(0, 0, canvasMini.width, canvasMini.height);
    miniCtx.fillStyle = '#0d1b18';
    miniCtx.fillRect(0, 0, canvasMini.width, canvasMini.height);

    const scaleX = canvasMini.width / WIDTH;
    const scaleY = canvasMini.height / HEIGHT;

    for (const structure of state.structures) {
      miniCtx.fillStyle = 'rgba(210,220,180,0.18)';
      miniCtx.fillRect(structure.x * scaleX, structure.y * scaleY, structure.w * scaleX, structure.h * scaleY);
    }

    for (const resource of state.resources) {
      if (resource.collected) continue;
      miniCtx.fillStyle = '#d4df8a';
      miniCtx.beginPath();
      miniCtx.arc(resource.x * scaleX, resource.y * scaleY, 2, 0, Math.PI * 2);
      miniCtx.fill();
    }

    miniCtx.fillStyle = '#ffb14a';
    miniCtx.beginPath();
    miniCtx.arc(state.campfire.x * scaleX, state.campfire.y * scaleY, 3, 0, Math.PI * 2);
    miniCtx.fill();

    for (const enemy of state.enemies) {
      miniCtx.fillStyle = '#d46d59';
      miniCtx.beginPath();
      miniCtx.arc(enemy.x * scaleX, enemy.y * scaleY, 2, 0, Math.PI * 2);
      miniCtx.fill();
    }

    miniCtx.fillStyle = '#e8e9dc';
    miniCtx.beginPath();
    miniCtx.arc(state.player.x * scaleX, state.player.y * scaleY, 3, 0, Math.PI * 2);
    miniCtx.fill();
  }

  const keys = {};
  document.addEventListener('keydown', (e) => {
    keys[e.code] = true;
    if (e.code === 'KeyE') doInteract();
    if (e.code === 'KeyI') {
      ui.inventory.classList.toggle('open');
      if (ui.inventory.classList.contains('open')) setToast('Inventory open');
    }
    if (e.code === 'KeyM') {
      setToast('Map synced to the field display.');
    }
    if (e.code === 'KeyF') {
      state.player.flashlight = !state.player.flashlight;
      setToast(state.player.flashlight ? 'Flashlight on.' : 'Flashlight off.');
    }
    if (e.code === 'Space') attack();
    if (e.code === 'Escape') ui.inventory.classList.remove('open');
    if (e.code.startsWith('Digit')) {
      const idx = Number(e.code.replace('Digit', '')) - 1;
      if (idx >= 0 && idx < state.quickSlots.length) useItem(state.quickSlots[idx].type, false);
    }
  });

  document.addEventListener('keyup', (e) => { keys[e.code] = false; });
  document.getElementById('closeInv').addEventListener('click', () => ui.inventory.classList.remove('open'));
  document.querySelectorAll('[data-craft]').forEach((btn) => {
    btn.addEventListener('click', () => craftItem(btn.dataset.craft));
  });

  const touchUse = document.getElementById('touchUse');
  const touchHit = document.getElementById('touchHit');
  const touchRun = document.getElementById('touchRun');
  touchUse.addEventListener('click', () => doInteract());
  touchHit.addEventListener('click', () => attack());
  touchRun.addEventListener('click', () => { state.player.sprinting = true; });

  function gameLoop(ts) {
    if (!state.running) {
      requestAnimationFrame(gameLoop);
      return;
    }

    const dt = Math.min((ts - (gameLoop.last || ts)) / 1000, 0.033);
    gameLoop.last = ts;

    state.timeMinutes += dt * 11.5;
    if (state.timeMinutes >= 24 * 60) {
      state.day += 1;
      state.timeMinutes -= 24 * 60;
    }

    updatePlayer(dt);
    updateEnemies(dt);
    spawnWave();
    updateResourceInteractions();
    updateObjectiveText();
    updateUI();
    refreshInventory();
    drawWorld();
    requestAnimationFrame(gameLoop);
  }

  window.addEventListener('resize', resizeCanvas);
  resizeCanvas();
  refreshInventory();
  updateUI();
  updateObjectiveText();
  requestAnimationFrame(gameLoop);
})();
</script>
"
