+(()=>{'use strict';
+const $=s=>document.querySelector(s), canvas=$('#world'),ctx=canvas.getContext('2d'), mini=$('#minimap'),mx=mini.getContext('2d');
+const W=2400,H=1800,TAU=Math.PI*2,clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),randSeed=(n)=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
