function toggleInventory(){inventoryOpen=!inventoryOpen;$('#inventory').classList.toggle('open',inventoryOpen);if(inventoryOpen)renderInventory();}
function useItem(k){if(!(bag[k]>0)){notice(`NO ${itemDefs[k].name.toUpperCase()} LEFT`);return;}if(k==='water'){player.thirst=clamp(player.thirst+38,0,100);}else if(k==='food'){player.hunger=clamp(player.hunger+34,0,100);}else if(k==='med'){player.hp=clamp(player.hp+55,0,100);}else if(k==='bandage'){player.hp=clamp(player.hp+28,0,100);}bag[k]--;syncUI();if(inventoryOpen)renderInventory();notice(`${itemDefs[k].name.toUpperCase()} USED`);}
function craft(k){if(k==='fire'){if(bag.wood<3||bag.rag<1){notice('NEED 3 WEATHERED WOOD + 1 CLOTH RAG');return;}bag.wood-=3;bag.rag--;gain('fire');notice('CAMPFIRE KIT CRAFTED — RETURN TO MILLER’S CROSSING');}else{if(bag.rag<2){notice('NEED 2 CLOTH RAGS');return;}bag.rag-=2;gain('bandage');notice('CLOTH BANDAGE CRAFTED');}renderInventory();syncUI();}
function nearestNode(){let best=null,dist=Infinity;for(const n of nodes){if(n.used)continue;let d=Math.hypot(n.x-player.x,n.y-player.y);if(d<dist){best=n;dist=d;}}return {node:best,dist};}
function interact(){if(gameOver)return;let {node,dist}=nearestNode();let bd=Math.hypot(player.x-base.x,player.y-base.y);if(bag.fire>0&&bd<78&&!firePlaced){bag.fire--;firePlaced={x:base.x,y:base.y+26};fireLit=0;notice('CAMPFIRE KIT PLACED — PRESS E TO LIGHT');syncUI();return;}if(firePlaced&&fireLit===0&&Math.hypot(player.x-firePlaced.x,player.y-firePlaced.y)<72){fireLit=1;notice('CAMPFIRE LIT — HOLD THIS GROUND UNTIL DAWN');$('#objectiveText').textContent='Protect the fire. Survive until dawn.';return;}if(node&&dist<55){node.used=true;let items=[];for(const [k,n] of Object.entries(node.loot)){let got=gain(k,n);if(got)items.push(`${got} ${itemDefs[k].name.toLowerCase()}${got>1?'s':''}`);}notice(`${node.label}: ${items.length?items.join(', '):'nothing useful'}`);syncUI();return;}notice('NOTHING TO SEARCH HERE');}
function melee(){if(gameOver)return;attackFlash=.22;let candidates=zombies.filter(z=>z.hp>0).map(z=>({z,d:Math.hypot(z.x-player.x,z.y-player.y)})).filter(o=>o.d<60).sort((a,b)=>a.d-b.d);if(!candidates.length){notice('SWING MISSED');return;}let z=candidates[0].z;z.hp-=bag.knife?36:24;z.x+=player.faceX*11;z.y+=player.faceY*11;if(z.hp<=0){kills++;notice('INFECTED DOWN');if(Math.random()<.38)gain(Math.random()<.5?'scrap':'rag');}else notice('HIT — KEEP YOUR DISTANCE');}
